1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value. At
42	// the envelope's top level that comparison is case-insensitive for the five
43	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
44	// that differs only in ASCII letter case — including one JSON-escaped — names
45	// the same field and corrupts the read instead of overriding it. A spelling
46	// that Unicode case-folds onto one of those fields yet is not an ASCII case
47	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
48	// is likewise corruption even when it is the only spelling present, since
49	// encoding/json's own tag matching would fill the field from it; a later
50	// "circuitſ": [] must never read the circuits as empty and drop them on the
51	// next commit.
52	type envelope struct {
53		Format    int               `json:"format"`
54		Circuits  []persistCircuit  `json:"circuits"`
55		Setups    []persistSetup    `json:"setups"`
56		Jobs      []persistJob      `json:"jobs"`
57		Artifacts []persistArtifact `json:"artifacts,omitempty"`
58	}
59	
60	// envelopeWire is the decoding-only shape: circuit records arrive raw so
61	// their own strict decoder can require every field explicitly.
62	type envelopeWire struct {
63		Format    int               `json:"format"`
64		Circuits  []json.RawMessage `json:"circuits"`
65		Setups    []persistSetup    `json:"setups"`
66		Jobs      []persistJob      `json:"jobs"`
67		Artifacts []persistArtifact `json:"artifacts,omitempty"`
68	}
69	
70	func (e *envelope) UnmarshalJSON(raw []byte) error {
71		// Reject repeated keys before decoding: encoding/json silently keeps the
72		// last value of a duplicate. The walk is layered so a repeated field is
73		// attributed to the record it belongs to (a duplicate "frozen" inside
74		// circuit #3, not a generic envelope complaint).
75		if err := scanEnvelopeDuplicates(raw); err != nil {
76			return err
77		}
78		var wire envelopeWire
79		if err := json.Unmarshal(raw, &wire); err != nil {
80			var se StoreError
81			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
82				return err // an inner record decoder already named the problem
83			}
84			return corruptf("data file envelope is not valid JSON: %v", err)
85		}
86		e.Format = wire.Format
87		e.Setups = wire.Setups
88		e.Jobs = wire.Jobs
89		e.Artifacts = wire.Artifacts
90		if wire.Circuits == nil {
91			e.Circuits = nil
92		} else {
93			e.Circuits = make([]persistCircuit, len(wire.Circuits))
94		}
95		for i, craw := range wire.Circuits {
96			var record persistCircuit
97			if err := json.Unmarshal(craw, &record); err != nil {
98				var se StoreError
99				if errors.As(err, &se) {
100					// Re-tag as one corruption error carrying the record index,
101					// so the detail survives errors.As unwrapping in loadLocked.
102					return StoreError{Kind: ErrDataCorrupt.Kind,
103						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
104				}
105				return corruptf("circuit record #%d: %v", i+1, err)
106			}
107			e.Circuits[i] = record
108		}
109		return nil
110	}
111	
112	// envelopeTopFields are the five fields an envelope may carry. Their
113	// canonical (standard lowercase) spellings are the wire tags on envelope and
114	// envelopeWire; JSON keys are tokenized after unescaping.
115	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
116	
117	// canonicalEnvelopeField reports the standard lowercase name of one of the
118	// five envelope fields when key names it under any ASCII letter-case spelling
119	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
120	// tokenizer, so an escaped spelling of any such form lands here too. A
121	// non-canonical key (different length or a mismatching byte, including
122	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
123	func canonicalEnvelopeField(key string) string {
124		for _, field := range envelopeTopFields {
125			if len(key) != len(field) {
126				continue
127			}
128			i := 0
129			for i < len(key) {
130				c := key[i]
131				if c >= 'A' && c <= 'Z' {
132					c += 'a' - 'A'
133				}
134				if c != field[i] {
135					break
136				}
137				i++
138			}
139			if i == len(field) {
140				return field
141			}
142		}
143		return ""
144	}
145	
146	// envelopeFieldLookalike reports the standard lowercase name of one of the
147	// five envelope fields when key names it under a spelling encoding/json's
148	// struct-tag matching would fold onto the field but which is not an accepted
149	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
150	// matching folds with the Unicode simple case-folding rules
151	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
152	// the JSON escape u017f — keys arrive here already unescaped) names the
153	// circuits field exactly like "circuits", even standing alone. Such a
154	// lookalike is damage whatever its value: a later "circuitſ": [] would
155	// otherwise override a populated circuits array through last-value-wins and
156	// the records would vanish on the next commit. A key that does not fold onto
157	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
158	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
159	// the ordinary unknown-member handling.
160	func envelopeFieldLookalike(key string) string {
161		if canonicalEnvelopeField(key) != "" {
162			return "" // an accepted ASCII spelling, not a lookalike
163		}
164		for _, field := range envelopeTopFields {
165			if strings.EqualFold(key, field) {
166				return field
167			}
168		}
169		return ""
170	}
171	
172	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
173	// repeated object key. The five known top-level fields are identified case-
174	// insensitively: two spellings that differ only in ASCII letter case (both
175	// keys already JSON-unescaped at this point) are the same field, in whatever
176	// order they appear and whether or not their values agree, so a later
177	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
178	// json's last-value-wins struct matching. Such a pair is reported as a
179	// duplicated top-level field named by its standard lowercase spelling.
180	//
181	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
182	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
183	// directly written or ſ-escaped) is rejected outright as data corruption:
184	// encoding/json would match it onto the field, so ignoring it as unknown
185	// could let its value replace the real one (an empty array hiding every
186	// record), and accepting it would let the records vanish on the next commit.
187	// The rule holds for the lookalike appearing alone — value a legal record, an
188	// empty array or null alike — and for it appearing beside the canonical
189	// spelling or an ASCII case variant, in either order and whether the values
190	// agree. The error names both the standard field and the actual spelling.
191	//
192	// Circuit records are scanned one level deep only — their top-level fields
193	// are checked here (with the record's 1-based index reported), while values
194	// such as the constraint definition are skipped and left to their own strict
195	// decoders. Every other envelope member is scanned recursively so a
196	// duplicated key anywhere in committed data fails the read instead of
197	// silently resolving to its last value.
198	func scanEnvelopeDuplicates(raw []byte) error {
199		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
200		dec.UseNumber()
201		open, err := dec.Token()
202		if err != nil || open != json.Delim('{') {
203			return corruptf("data file envelope must be a JSON object")
204		}
205		// Exact spellings retain the pre-existing check for unknown keys;
206		// canonical names remember a known field's first occurrence regardless
207		// of the case it was written in.
208		seenTop := make(map[string]bool)
209		seenCanonical := make(map[string]bool)
210		for dec.More() {
211			keyTok, err := dec.Token()
212			if err != nil {
213				return corruptf("data file envelope is not valid JSON: %v", err)
214			}
215			key, ok := keyTok.(string)
216			if !ok {
217				return corruptf("data file envelope is not valid JSON")
218			}
219			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
220			// matching would read as a known field ("circuitſ" with long s,
221			// directly written or ſ-escaped) before anything else. It is damage
222			// even on its own and whatever its value — a legal record, an empty
223			// array or null — and whether it precedes or follows the canonical or
224			// an ASCII case-variant spelling: the read may neither ignore it as an
225			// unknown member nor choose one of the values and carry on.
226			if canonical := envelopeFieldLookalike(key); canonical != "" {
227				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
228					canonical, key)
229			}
230			if canonical := canonicalEnvelopeField(key); canonical != "" {
231				if seenCanonical[canonical] {
232					if key == canonical {
233						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
234					}
235					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
236						canonical, key)
237				}
238				seenCanonical[canonical] = true
239				if canonical == "circuits" {
240					if err := scanCircuitArrayDuplicates(dec); err != nil {
241						return err
242					}
243					continue
244				}
245				if canonical == "jobs" {
246					if err := scanJobArrayDuplicates(dec); err != nil {
247						return err
248					}
249					continue
250				}
251				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
252					return err
253				}
254				continue
255			}
256			if seenTop[key] {
257				return corruptf("data file envelope contains duplicate field %q", key)
258			}
259			seenTop[key] = true
260			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
261				return err
262			}
263		}
264		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
265			return corruptf("data file envelope is not valid JSON")
266		}
267		if _, err := dec.Token(); err != io.EOF {
268			return corruptf("data file envelope is not valid JSON: trailing data after the object")
269		}
270		return nil
271	}
272	
273	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
274	// opening bracket and checks only each record's own top-level keys. The
275	// enclosing key may carry any case spelling, but the field it names is the
276	// canonical "circuits". A null array stays the pre-existing "no records"
277	// reading.
278	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
279		tok, err := dec.Token()
280		if err != nil {
281			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
282		}
283		if tok == nil { // null: json.Unmarshal would produce no records
284			return nil
285		}
286		if tok != json.Delim('[') {
287			return corruptf("data file envelope field \"circuits\" must be an array")
288		}
289		index := 0
290		for dec.More() {
291			index++
292			what := fmt.Sprintf("circuit record #%d", index)
293			open, err := dec.Token()
294			if err != nil {
295				return corruptf("%s is not valid JSON: %v", what, err)
296			}
297			if open == nil {
298				return corruptf("%s must be a JSON object, not null", what)
299			}
300			if open != json.Delim('{') {
301				return corruptf("%s must be a JSON object", what)
302			}
303			seen := make(map[string]bool)
304			for dec.More() {
305				keyTok, err := dec.Token()
306				if err != nil {
307					return corruptf("%s is not valid JSON: %v", what, err)
308				}
309				key, ok := keyTok.(string)
310				if !ok {
311					return corruptf("%s is not valid JSON", what)
312				}
313				if seen[key] {
314					return corruptf("%s contains duplicate field %q", what, key)
315				}
316				seen[key] = true
317				// Skip the whole value without descending: nested objects
318				// (definition) own their own strict duplicate checks.
319				var skip json.RawMessage
320				if err := dec.Decode(&skip); err != nil {
321					return corruptf("%s is not valid JSON: %v", what, err)
322				}
323			}
324			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
325				return corruptf("%s is not valid JSON", what)
326			}
327		}
328		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
329			return corruptf("data file envelope field \"circuits\" is not valid JSON")
330		}
331		return nil
332	}
333	
334	// scanJobArrayDuplicates consumes one "jobs" value positioned at its opening
335	// bracket. It is the jobs-array counterpart of scanCircuitArrayDuplicates and
336	// exists so a structural problem inside one job is attributed to that job — by
337	// its id when the id is a legible string, else by its 1-based position —
338	// rather than to an opaque "jobs" element index.
339	//
340	// Besides an exact repeated member key (compared after JSON unescaping, as for
341	// every other record), it enforces the pinned-version uniqueness rule here,
342	// before any value is decoded — the same rejectAmbiguousJobVersion rule the
343	// single-record decode applies, so both readings agree on which spellings
344	// name the version field and on the refusal message. Catching it here —
345	// rather than only in the record decoder — also covers two byte-identical
346	// "version" keys, which the record's strict member walk would otherwise
347	// reject without the id in hand. The verdict is deferred to the end of each
348	// record solely so a version written before the id still names the job; every
349	// token is consumed regardless. Nested member values keep the ordinary
350	// recursive duplicate scan. A null array stays the pre-existing "no jobs"
351	// reading.
352	func scanJobArrayDuplicates(dec *json.Decoder) error {
353		tok, err := dec.Token()
354		if err != nil {
355			return corruptf("data file envelope field \"jobs\" is not valid JSON: %v", err)
356		}
357		if tok == nil { // null: json.Unmarshal would produce no jobs
358			return nil
359		}
360		if tok != json.Delim('[') {
361			return corruptf("data file envelope field \"jobs\" must be an array")
362		}
363		index := 0
364		for dec.More() {
365			index++
366			positional := fmt.Sprintf("job record #%d", index)
367			open, err := dec.Token()
368			if err != nil {
369				return corruptf("%s is not valid JSON: %v", positional, err)
370			}
371			if open == nil {
372				return corruptf("%s must be a JSON object, not null", positional)
373			}
374			if open != json.Delim('{') {
375				return corruptf("%s must be a JSON object", positional)
376			}
377			var (
378				id         string
379				seenExact  = make(map[string]bool)
380				dupKey     string
381				memberKeys []string
382				nestedErr  error
383			)
384			for dec.More() {
385				keyTok, err := dec.Token()
386				if err != nil {
387					return corruptf("%s is not valid JSON: %v", positional, err)
388				}
389				key, ok := keyTok.(string)
390				if !ok {
391					return corruptf("%s is not valid JSON", positional)
392				}
393				// Consume the whole value first; judgments below use only the key
394				// (and, for id, the already-captured bytes). Job members are
395				// scalars, but an unknown member may carry an object/array whose
396				// own duplicate keys must still fail the read.
397				var value json.RawMessage
398				if err := dec.Decode(&value); err != nil {
399					return corruptf("%s is not valid JSON: %v", positional, err)
400				}
401				if key == "id" {
402					if idVal, ierr := storedRecordShape.string(value, positional+` field "id"`); ierr == nil {
403						id = idVal
404					}
405				}
406				memberKeys = append(memberKeys, key)
407				if seenExact[key] && dupKey == "" {
408					dupKey = key
409				}
410				seenExact[key] = true
411				trimmed := bytes.TrimSpace(value)
412				if nestedErr == nil && len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[') {
413					nd := json.NewDecoder(bytes.NewReader(trimmed))
414					nestedErr = skipValueWithDupKeys(nd, positional+" field "+strconv.Quote(key))
415				}
416			}
417			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
418				return corruptf("%s is not valid JSON", positional)
419			}
420			what := positional
421			if id != "" {
422				what = fmt.Sprintf("stored job record %q", id)
423			}
424			// A repeated version spelling is the pinned-version ambiguity and gets
425			// the specific message, including when both keys are byte-identical.
426			if err := rejectAmbiguousJobVersion(what, memberKeys); err != nil {
427				return err
428			}
429			if dupKey != "" {
430				return corruptf("%s contains duplicate field %q", what, dupKey)
431			}
432			if nestedErr != nil {
433				return nestedErr
434			}
435		}
436		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
437			return corruptf("data file envelope field \"jobs\" is not valid JSON")
438		}
439		return nil
440	}
441	
442	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
443	// recursively rejecting duplicate object keys.
444	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
445		tok, err := dec.Token()
446		if err != nil {
447			return corruptf("%s is not valid JSON: %v", what, err)
448		}
449		delim, ok := tok.(json.Delim)
450		if !ok {
451			return nil // scalar (including null)
452		}
453		switch delim {
454		case '{':
455			seen := make(map[string]bool)
456			for dec.More() {
457				keyTok, err := dec.Token()
458				if err != nil {
459					return corruptf("%s is not valid JSON: %v", what, err)
460				}
461				key, ok := keyTok.(string)
462				if !ok {
463					return corruptf("%s is not valid JSON", what)
464				}
465				if seen[key] {
466					return corruptf("%s contains duplicate field %q", what, key)
467				}
468				seen[key] = true
469				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
470					return err
471				}
472			}
473			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
474				return corruptf("%s is not valid JSON", what)
475			}
476		case '[':
477			index := 0
478			for dec.More() {
479				index++
480				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
481					return err
482				}
483			}
484			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
485				return corruptf("%s is not valid JSON", what)
486			}
487		}
488		return nil
489	}
