532	// Strict decoding of committed circuit records.
533	//
534	// A circuit record in data.json must name each of name, version, constraints,
535	// public_inputs, private_inputs, frozen and description exactly once, with
536	// the exact JSON type the writer emits (string / integer / integer / integer
537	// / integer / boolean / string). A missing key, a null, a wrong type or a
538	// repeated key is data corruption and refuses the whole directory read: a
539	// missing or null frozen flag must not silently read as false (turning a
540	// frozen version back into an editable draft), and a repeated key must not
541	// resolve to its last value. An explicit 0, false or "" is an ordinary value
542	// and stays legal. The definition member remains the one optional field: it
543	// may be absent or null (the legacy counts-only state); when present it goes
544	// through the strict persistDefinition decoder.
545	//
546	// Only shape is judged here. The domain rules (non-blank name, positive
547	// version and constraint count, non-negative input counts) keep being
548	// re-checked by validateEnvelope.
549	
550	var persistCircuitFields = []string{
551		"name", "version", "constraints", "public_inputs", "private_inputs",
552		"frozen", "description", "definition",
553	}
554	
555	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
556	// tagged for committed data: every structural failure in a stored circuit
557	// record is data corruption, never a bad request.
558	var storedRecordShape = jsonShape{fail: corruptf}
559	
560	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
561		const what = "stored circuit record"
562		if string(bytes.TrimSpace(raw)) == "null" {
563			return corruptf("%s must be a JSON object, not null", what)
564		}
565		members, err := strictCircuitObject(raw, what)
566		if err != nil {
567			return err
568		}
569	
570		var out persistCircuit
571	
572		requireString := func(key string, dst *string) error {
573			r, err := storedRecordShape.require(members, key, what)
574			if err != nil {
575				return err
576			}
577			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
578			if err != nil {
579				return err
580			}
581			*dst = v
582			return nil
583		}
584		requireInt := func(key string, dst *int) error {
585			r, err := storedRecordShape.require(members, key, what)
586			if err != nil {
587				return err
588			}
589			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
590			if err != nil {
591				return err
592			}
593			*dst = v
594			return nil
595		}
596	
597		if err := requireString("name", &out.Name); err != nil {
598			return err
599		}
600		if err := requireInt("version", &out.Version); err != nil {
601			return err
602		}
603		if err := requireInt("constraints", &out.Constraints); err != nil {
604			return err
605		}
606		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
607			return err
608		}
609		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
610			return err
611		}
612		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
613		if err != nil {
614			return err
615		}
616		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
617		if err != nil {
618			return err
619		}
620		if err := requireString("description", &out.Description); err != nil {
621			return err
622		}
623	
624		// definition is the only optional member: absent or null both mean the
625		// counts-only legacy state.
626		if defRaw, present := members["definition"]; present {
627			if string(bytes.TrimSpace(defRaw)) != "null" {
628				var def persistDefinition
629				if err := json.Unmarshal(defRaw, &def); err != nil {
630					var se StoreError
631					if errors.As(err, &se) {
632						return err // already reported as data corruption
633					}
634					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
635				}
636				out.Definition = &def
637			}
638		}
639	
640		*c = out
641		return nil
642	}
