33				if existing.Description != c.Description {
34					return false, conflictf("circuit %q version %d already exists with a different description", c.Name, c.Version)
35				}
36				result = circuitFromPersist(*existing)
37				return false, nil
38			}
39			record := persistCircuit{
40				Name: c.Name, Version: c.Version,
41				Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
42				Frozen: false, Description: c.Description,
43			}
44			s.data.Circuits = append(s.data.Circuits, record)
45			result = circuitFromPersist(record)
46			return true, nil
47		})
48		return result, err
49	}
50	
51	// UpdateCircuit modifies a draft circuit version. It must target an existing,
52	// unfrozen version explicitly: unknown versions yield ErrNotFound and frozen
53	// versions yield ErrFrozen. On success the counts and description are
54	// replaced as one atomic change; partial updates can never be observed.
55	//
56	// This is the whole-record replacement entry point: the three counts and the
57	// description carried by c override the stored record outright (zero values
58	// included). Field-by-field editing with omitted-field preservation lives in
59	// UpdateCircuitPartial; both entry points run the same draft-update rules
60	// through the circuitMutation helpers below.
61	func (s *Store) UpdateCircuit(c Circuit) (Circuit, error) {
62		if err := validateCircuitKey(c.Name, c.Version); err != nil {
63			return Circuit{}, err
64		}
65		mutation := circuitMutation{
66			Constraints:   c.Constraints,
67			PublicInputs:  c.PublicInputs,
68			PrivateInputs: c.PrivateInputs,
69			Description:   c.Description,
70		}
71		// Whole replacement judges the supplied counts before the target is
72		// looked up, so an illegal replacement reports invalid argument even for
73		// unknown or frozen versions.
74		if err := validateMutationCounts(mutation); err != nil {
75			return Circuit{}, err
76		}
77	
78		var result Circuit
79		err := s.withLock(func() (bool, error) {
80			existing := findCircuit(s.data.Circuits, c.Name, c.Version)
81			if existing == nil {
82				return false, notFoundf("circuit %q version %d does not exist", c.Name, c.Version)
83			}
84			if existing.Frozen {
85				return false, frozenf("circuit %q version %d is frozen and its description cannot be modified", c.Name, c.Version)
86			}
87			if err := validateMutationDefinition(*existing, mutation); err != nil {
88				return false, err
89			}
90			result = applyCircuitMutation(existing, mutation)
91			return true, nil
92		})
93		return result, err
94	}
95	
96	// PartialCircuit carries optional replacement fields for one draft circuit
97	// version. A nil pointer leaves the stored field untouched; a non-nil pointer
98	// — even to zero or to the empty string — replaces the field. This lets a
99	// caller change exactly one field without restating the others.
100	type PartialCircuit struct {
101		Constraints   *int
102		PublicInputs  *int
103		PrivateInputs *int
104		Description   *string
105	}
106	
107	// UpdateCircuitPartial modifies selected fields of a draft circuit version.
108	//
109	// Only fields present in patch are changed; omitted fields keep their stored
110	// values. A non-nil pointer still replaces its field even when it points at
111	// zero or the empty string (explicit zero clears an input count, an empty
112	// string clears the description). The whole merged result is validated
113	// before anything is committed: constraints must stay positive and input
114	// counts non-negative, and when a constraint definition is already imported
115	// the merged counts must keep it legal (exact constraint count, every
116	// referenced wire inside the new input layout). Any rejected field refuses
117	// the entire change — description, counts and the stored definition all
118	// remain as they were. The merged result is checked through the same
119	// circuitMutation helpers as UpdateCircuit's whole replacement.
120	//
121	// Existence and frozen state are settled before the merged counts are
122	// judged: unknown versions yield ErrNotFound and frozen versions
123	// ErrFrozen, even when the patch carries an illegal count or no field at
124	// all. A patch that provides no modifiable field at all returns the stored
125	// record unchanged and commits nothing (no new version, no data write).
126	func (s *Store) UpdateCircuitPartial(name string, version int, patch PartialCircuit) (Circuit, error) {
127		if err := validateCircuitKey(name, version); err != nil {
128			return Circuit{}, err
129		}
130		hasField := patch.Constraints != nil || patch.PublicInputs != nil ||
131			patch.PrivateInputs != nil || patch.Description != nil
132	
133		var result Circuit
134		err := s.withLock(func() (bool, error) {
135			existing := findCircuit(s.data.Circuits, name, version)
136			if existing == nil {
137				return false, notFoundf("circuit %q version %d does not exist", name, version)
138			}
139			if existing.Frozen {
140				return false, frozenf("circuit %q version %d is frozen and cannot be modified", name, version)
141			}
142			// Merge the provided fields over the stored record; omitted fields
143			// keep their committed values, so the merged counts are always the
144			// complete result this modification would leave behind.
145			mutation := circuitMutation{
146				Constraints:   existing.Constraints,
147				PublicInputs:  existing.PublicInputs,
148				PrivateInputs: existing.PrivateInputs,
149				Description:   existing.Description,
150			}
151			if patch.Constraints != nil {
152				mutation.Constraints = *patch.Constraints
153			}
154			if patch.PublicInputs != nil {
155				mutation.PublicInputs = *patch.PublicInputs
156			}
157			if patch.PrivateInputs != nil {
158				mutation.PrivateInputs = *patch.PrivateInputs
159			}
160			if patch.Description != nil {
161				mutation.Description = *patch.Description
162			}
163			if err := validateMutationCounts(mutation); err != nil {
164				return false, err
165			}
166			if err := validateMutationDefinition(*existing, mutation); err != nil {
167				return false, err
168			}
169			// No modifiable field was provided: return the stored record without
170			// committing anything.
171			if !hasField {
172				result = circuitFromPersist(*existing)
173				return false, nil
174			}
175			result = applyCircuitMutation(existing, mutation)
176			return true, nil
177		})
178		return result, err
179	}
180	
181	// --- draft update internals -----------------------------------------------
182	//
183	// circuitMutation is the complete set of updatable draft fields one
184	// modification would leave committed: the three counts and the description.
185	// Both public update entry points resolve their request into this type —
186	// UpdateCircuit takes all four values from the request, UpdateCircuitPartial
187	// merges request fields over the stored record — and then share the same
188	// count rules, imported-definition compatibility check and commit, so the
189	// two usages can never drift apart. A mutation never replaces the stored
190	// constraint definition; it is only checked against it.
191	type circuitMutation struct {
192		Constraints   int
193		PublicInputs  int
194		PrivateInputs int
195		Description   string
196	}
197	
198	// validateMutationCounts holds the basic count rules for any draft update:
199	// constraints must be greater than zero and both input counts must not be
200	// negative. The rules are judged on the mutation's complete resulting
201	// counts, not on the supplied fields alone.
202	func validateMutationCounts(m circuitMutation) error {
203		return validateCounts(m.Constraints, m.PublicInputs, m.PrivateInputs)
204	}
205	
206	// validateMutationDefinition holds the rule shared with imported
207	// definitions: when the version already has one, the mutation's complete
208	// resulting counts must keep it legal — exactly as many constraints as the
209	// definition and every referenced wire inside the resulting public/private
210	// input layout. An unreadable stored definition is reported as data
211	// corruption. A version without a definition imposes no extra rule.
212	func validateMutationDefinition(existing persistCircuit, m circuitMutation) error {
213		if existing.Definition == nil {
214			return nil
215		}
216		parsed, perr := definitionFromPersist(*existing.Definition, existing.PublicInputs, existing.PrivateInputs)
217		if perr != nil {
218			return corruptf("stored definition for %q v%d is unreadable: %v", existing.Name, existing.Version, perr)
219		}
220		if !parsed.compatibleWith(m.Constraints, m.PublicInputs, m.PrivateInputs) {
221			return invalidf("update rejected: it would make the imported constraint definition illegal (constraint count or wire layout mismatch); the whole change is refused")
222		}
223		return nil
224	}
225	
226	// applyCircuitMutation commits a validated mutation onto the stored draft
227	// record, overwriting the three counts and the description together. The
228	// name, version, frozen flag and imported definition are never touched. The
229	// caller is responsible for all validation and for holding the store lock.
230	func applyCircuitMutation(existing *persistCircuit, m circuitMutation) Circuit {
231		existing.Constraints = m.Constraints
232		existing.PublicInputs = m.PublicInputs
233		existing.PrivateInputs = m.PrivateInputs
234		existing.Description = m.Description
235		return circuitFromPersist(*existing)
236	}
237	
238	// FreezeCircuit freezes a circuit version. Unknown versions yield
239	// ErrNotFound. Freezing an already-frozen version returns that version
240	// unchanged (idempotent). Once frozen, name, version and the three counts
241	// can never change again.
242	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
243		if err := validateCircuitKey(name, version); err != nil {
244			return Circuit{}, err
245		}
246	
247		var result Circuit
248		err := s.withLock(func() (bool, error) {
249			existing := findCircuit(s.data.Circuits, name, version)
250			if existing == nil {
251				return false, notFoundf("circuit %q version %d does not exist", name, version)
252			}
253			if existing.Frozen {
254				result = circuitFromPersist(*existing)
255				return false, nil
256			}
257			existing.Frozen = true
258			result = circuitFromPersist(*existing)
259			return true, nil
260		})
261		return result, err
262	}
263	
264	// CopyCircuit creates a new draft version of a circuit name by copying a
265	// frozen source version. The target version must be a positive integer
266	// different from the source version; it need not be consecutive or greater.
267	//
268	// The copy carries over the source's description, constraint count, public
269	// and private input counts, and — when the source has one — its complete
270	// constraint definition (modulus, constraint order and wire layout). A
271	// counts-only source produces a counts-only target with no definition. The
272	// new draft is fully independent: updating, re-importing or freezing it
273	// never touches the source, and the source's compiled artifacts, trusted
274	// setup and registered jobs are never copied or bound to the target. The
275	// target must register its own setup and compile its own artifact after
276	// freezing; the source's hash cannot satisfy the target's input checks or
277	// job bindings.
278	//
279	// Copying is idempotent: if the target already exists as a draft whose
280	// description, counts and definition are semantically equal to the source,
281	// the stored target is returned unchanged and nothing is written. A frozen
282	// target or a target whose description, counts or definition has changed
283	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
284	// source ErrNotFrozen; the source is always checked before the target.
285	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
286		if err := validateCircuitKey(name, version); err != nil {
287			return Circuit{}, err
288		}
289		if err := validateCircuitKey(name, toVersion); err != nil {
290			return Circuit{}, err
291		}
292		if version == toVersion {
293			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
294		}
295	
296		var result Circuit
297		err := s.withLock(func() (bool, error) {
298			source := findCircuit(s.data.Circuits, name, version)
299			if source == nil {
300				return false, notFoundf("circuit %q version %d does not exist", name, version)
301			}
302			if !source.Frozen {
303				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
304			}
305			target := findCircuit(s.data.Circuits, name, toVersion)
306			if target != nil {
307				if target.Frozen {
308					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
309				}
310				if !circuitCopyMatches(*source, *target) {
311					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
312				}
313				result = circuitFromPersist(*target)
314				return false, nil
315			}
316			record := persistCircuit{
317				Name: name, Version: toVersion,
318				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
319				Frozen: false, Description: source.Description,
320			}
321			if source.Definition != nil {
322				def := *source.Definition
323				record.Definition = &def
324			}
325			s.data.Circuits = append(s.data.Circuits, record)
326			result = circuitFromPersist(record)
327			return true, nil
328		})
329		return result, err
330	}
331	
332	// RecordSetup records a trusted setup for one frozen circuit version. The
333	// record belongs exclusively to that name+version. Unknown versions yield
334	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
335	// setup for the same version is idempotent and adds no duplicate record.
336	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
337		if err := validateCircuitKey(name, version); err != nil {
338			return Setup{}, err
339		}
340	
341		var result Setup
342		err := s.withLock(func() (bool, error) {
343			circuit := findCircuit(s.data.Circuits, name, version)
344			if circuit == nil {
345				return false, notFoundf("circuit %q version %d does not exist", name, version)
346			}
347			if !circuit.Frozen {
348				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
349			}
350			if existing := findSetup(s.data.Setups, name, version); existing != nil {
351				result = setupFromPersist(*existing)
352				return false, nil
353			}
354			record := persistSetup{Name: name, Version: version}
355			s.data.Setups = append(s.data.Setups, record)
356			result = setupFromPersist(record)
357			return true, nil
358		})
359		return result, err
360	}
361	
362	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
363	// no proving computation runs, the accepted request alone is persisted.
364	//
365	// The job id must be non-empty and not only whitespace, circuit name and
366	// version must be explicit and Attempt must be positive. Failure reasons are
367	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
368	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
369	// refused submission leaves no job behind.
370	//
371	// A non-empty CompiledHash additionally binds the job to the pinned
372	// version's compiled artifact, matched as the exact string: a version with
373	// no compiled artifact yields ErrArtifactMissing and a hash that differs
374	// from that artifact's hash yields ErrArtifactMismatch. Artifacts of other
375	// names or versions never satisfy the binding. An empty CompiledHash leaves
376	// the job unbound and keeps the register-only behavior.
377	//
378	// Resubmitting the same id with the same request — including the same
379	// optional hash — returns the stored job; the same id with different content
380	// yields ErrConflict, reported before any artifact check of the new request.
381	// A stored job stays pinned to the version submitted, regardless of circuit
382	// versions added later.
383	func (s *Store) SubmitJob(job Job) (Job, error) {
384		if strings.TrimSpace(job.ID) == "" {
385			return Job{}, invalidf("job id must be non-empty and not only whitespace")
386		}
387		if strings.TrimSpace(job.Circuit) == "" {
388			return Job{}, invalidf("job %q must name a circuit", job.ID)
389		}
390		if job.Version <= 0 {
391			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
392		}
393		if job.Attempt <= 0 {
394			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
395		}
396		if job.Kind != "prove" {
397			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
398				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
399		}
400	
401		var result Job
402		err := s.withLock(func() (bool, error) {
403			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
404				if !sameJobRequest(*existing, job) {
405					return false, conflictf("job %q already exists with a different request", job.ID)
406				}
407				result = jobFromPersist(*existing)
408				return false, nil
409			}
410			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
411			if circuit == nil {
412				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
413			}
414			if !circuit.Frozen {
415				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
416			}
417			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
418				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
419					job.ID, job.Circuit, job.Version)
420			}
421			if job.CompiledHash != "" {
422				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
423				if artifact == nil {
424					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
425						job.ID, job.Circuit, job.Version)
426				}
427				if artifact.Hash != job.CompiledHash {
428					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
429						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
430				}
431			}
432			record := persistJob{
433				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
434				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
435				CompiledHash: job.CompiledHash,
436			}
437			s.data.Jobs = append(s.data.Jobs, record)
438			result = jobFromPersist(record)
439			return true, nil
440		})
441		return result, err
442	}
443	
444	// GetCircuit returns one circuit version, sorted-field populated exactly as
445	// stored. Unknown versions yield ErrNotFound.
446	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
447		if err := validateCircuitKey(name, version); err != nil {
448			return Circuit{}, err
449		}
450		var result Circuit
451		err := s.withLockRead(func() error {
452			existing := findCircuit(s.data.Circuits, name, version)
453			if existing == nil {
454				return notFoundf("circuit %q version %d does not exist", name, version)
455			}
456			result = circuitFromPersist(*existing)
457			return nil
458		})
459		return result, err
