462	// ListCircuits returns all stored circuit versions ordered by circuit name
463	// (lexicographically) and then by ascending version number.
464	func (s *Store) ListCircuits() ([]Circuit, error) {
465		var result []Circuit
466		err := s.withLockRead(func() error {
467			ordered := append([]persistCircuit(nil), s.data.Circuits...)
468			sort.Slice(ordered, func(i, j int) bool {
469				if ordered[i].Name != ordered[j].Name {
470					return ordered[i].Name < ordered[j].Name
471				}
472				return ordered[i].Version < ordered[j].Version
473			})
474			result = make([]Circuit, len(ordered))
475			for i, c := range ordered {
476				result[i] = circuitFromPersist(c)
477			}
478			return nil
479		})
480		return result, err
481	}
