451	// values. Both satisfied and unsatisfied assignments are successful
452	// evaluations and exit 0; the satisfied= field carries the verdict (with
453	// first_failure set when false). Only gating, input-format and data problems
454	// use the non-zero error exits.
455	func cmdInputCheck(f *cliFlags) int {
456		if ok, code := requireNameVersion("input-check", f); !ok {
457			return code
458		}
459		if f.file == "" {
