467		store, code := openStore(f)
468		if store == nil {
469			return code
470		}
471		defer store.Close()
472	
473		result, err := store.CheckInputFile(f.name, f.version, f.hash, f.file)
474		if err != nil {
475			return reportStoreError(err)
476		}
477		if result.Satisfied {
478			fmt.Printf("input check: satisfied=true name=%s version=%d hash=%s\n",
479				f.name, f.version, result.Hash)
480			return exitOK
481		}
482		fmt.Printf("input check: satisfied=false name=%s version=%d hash=%s first_failure=%d\n",
483			f.name, f.version, result.Hash, result.FirstFailure)
484		return exitOK
