func cmdConstraintImport(f *cliFlags) int {
	if ok, code := requireNameVersion("constraint-import", f); !ok {
		return code
	}
	if f.file == "" {
		fmt.Fprintln(os.Stderr, "error: --file is required for constraint-import")
		return exitUsage
	}
	store, code := openStore(f)
	if store == nil {
		return code
	}
	defer store.Close()

	def, err := store.ImportConstraints(f.name, f.version, f.file)
	if err != nil {
		return reportStoreError(err)
	}
	fmt.Printf("constraints imported: name=%s version=%d modulus=%s constraints=%d\n",
		f.name, f.version, def.Modulus, len(def.Constraints))
	return exitOK
}

func cmdCircuitCompile(f *cliFlags) int {
	if ok, code := requireNameVersion("circuit-compile", f); !ok {
		return code
	}
	store, code := openStore(f)
	if store == nil {
		return code
	}
	defer store.Close()

	artifact, err := store.CompileCircuit(f.name, f.version)
	if err != nil {
		return reportStoreError(err)
	}
	fmt.Printf("artifact: name=%s version=%d modulus=%d constraints=%d hash=%s\n",
		artifact.Name, artifact.Version, artifact.Modulus, artifact.Constraints, artifact.Hash)
	return exitOK
}

// cmdInputCheck prints the verdict on stdout without ever echoing private
// values. Both satisfied and unsatisfied assignments are successful
// evaluations and exit 0; the satisfied= field carries the verdict (with
// first_failure set when false). Only gating, input-format and data problems
// use the non-zero error exits.
func cmdInputCheck(f *cliFlags) int {
	if ok, code := requireNameVersion("input-check", f); !ok {
		return code
	}
	if f.file == "" {
		fmt.Fprintln(os.Stderr, "error: --file is required for input-check")
		return exitUsage
	}
	if f.hash == "" {
		fmt.Fprintln(os.Stderr, "error: --hash is required for input-check")
		return exitUsage
	}
	store, code := openStore(f)
	if store == nil {
		return code
	}
	defer store.Close()

	result, err := store.CheckInputFile(f.name, f.version, f.hash, f.file)
	if err != nil {
		return reportStoreError(err)
	}
	if result.Satisfied {
		fmt.Printf("input check: satisfied=true name=%s version=%d hash=%s\n",
			f.name, f.version, result.Hash)
		return exitOK
	}
	fmt.Printf("input check: satisfied=false name=%s version=%d hash=%s first_failure=%d\n",
		f.name, f.version, result.Hash, result.FirstFailure)
	return exitOK
}

package main

import (
	"flag"
	"fmt"
	"io"
)

func usageLine() {
	fmt.Println("usage: zkcircuit [demo|version|help]")
}

// cliFlags holds every flag the data commands accept.
type cliFlags struct {
	dir         string
	name        string
	version     int
	toVersion   int
	constraints int
	publicIn    int
	privateIn   int
	description string
	id          string
	attempt     int
	kind        string
	file        string
	hash        string
	// Set reports which value flags were explicitly provided on the command
	// line. circuit-update uses these to tell "omitted" apart from "given a
	// default value", so an omitted field keeps its stored value instead of
	// being written back as the flag default.
	constraintsSet bool
	publicInSet    bool
	privateInSet   bool
	descriptionSet bool
}

// newFlagSet builds the shared flag set. Defaults are chosen so the bare
// required flags (--dir/--name/--version or --dir/--id) already produce a
// valid request.
func newFlagSet(cmd string, out io.Writer) (*flag.FlagSet, *cliFlags) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(out)
	fs.Usage = func() {}
	var f cliFlags
	fs.StringVar(&f.dir, "dir", "", "数据目录")
	fs.StringVar(&f.name, "name", "", "电路名称")
	fs.IntVar(&f.version, "version", 0, "源电路版本号（正整数）")
	fs.IntVar(&f.toVersion, "to-version", 0, "目标电路版本号（正整数，须与源版本不同）")
	fs.IntVar(&f.constraints, "constraints", 8192, "约束数量（必须大于 0）")
	fs.IntVar(&f.publicIn, "public-inputs", 0, "公开输入数量（不得为负）")
	fs.IntVar(&f.privateIn, "private-inputs", 0, "私有输入数量（不得为负）")
	fs.StringVar(&f.description, "description", "", "版本描述")
	fs.StringVar(&f.id, "id", "", "作业编号")
	fs.IntVar(&f.attempt, "attempt", 1, "尝试次数（正整数）")
	fs.StringVar(&f.kind, "kind", "prove", "作业类型（当前只接受 prove）")
	fs.StringVar(&f.file, "file", "", "约束定义或输入的 JSON 文件")
	fs.StringVar(&f.hash, "hash", "", "编译产物 SHA-256 哈希（input-check 必填；job-submit 可选绑定）")
	return fs, &f
}

