14	// These tests pin the read-time contract for a circuit record already
15	// committed in data.json: name, version, constraints, public_inputs,
16	// private_inputs, frozen and description must each be present exactly once
17	// with the exact JSON type the writer emits. A missing key, null, wrong type
18	// or repeated key (including a key spelled through a JSON escape, or repeated
19	// with the same value) is data corruption: the whole directory fails to read
20	// rather than silently filling 0/false/"".
21	
22	// seedClosedStore creates a store, optionally seeds a complete circuit
23	// (definition imported, then frozen) and closes it, returning its directory.
24	func seedClosedStore(t *testing.T, frozen bool) string {
25		t.Helper()
26		dir := filepath.Join(t.TempDir(), "bench")
27		s, err := Open(dir)
28		if err != nil {
29			t.Fatal(err)
30		}
