33		seedDraftWithDef(t, s, "mul", 1, 1, 1, goodDef)
34		if frozen {
35			if _, err := s.FreezeCircuit("mul", 1); err != nil {
36				t.Fatal(err)
37			}
38			if _, err := s.RecordSetup("mul", 1); err != nil {
39				t.Fatal(err)
40			}
41			if _, err := s.CompileCircuit("mul", 1); err != nil {
42				t.Fatal(err)
