68	func requireCorruptAndUntouched(t *testing.T, dir string, bad []byte, wantField string) {
69		t.Helper()
70		s, err := Open(dir)
71		if err == nil {
72			s.Close()
73			t.Fatalf("damaged circuit record was accepted")
74		}
75		var se StoreError
76		if !errors.As(err, &se) || se.Kind != ErrDataCorrupt.Kind {
77			t.Fatalf("want ErrDataCorrupt, got %v", err)
78		}
79		if wantField != "" && !strings.Contains(err.Error(), wantField) {
80			t.Fatalf("error does not name the damaged field %q: %v", wantField, err)
81		}
82		left, rerr := os.ReadFile(filepath.Join(dir, dirDataFile))
83		if rerr != nil {
84			t.Fatal(rerr)
85		}
86		if string(left) != string(bad) {
87			t.Fatalf("refused read modified data.json\nwant: %q\n got: %q", bad, left)
88		}
89		if s2, err := Open(dir); err == nil {
90			s2.Close()
91			t.Fatalf("reopen accepted the damage")
92		} else if !errors.Is(err, ErrDataCorrupt) {
93			t.Fatalf("reopen: want ErrDataCorrupt, got %v", err)
94		}
95	}
