97	// TestCorruptCircuitRecordFieldsRefused damages each required field of a
98	// committed circuit record in turn; whether the version is a draft or frozen
99	// (trusted setup + compiled artifact), the directory must be unreadable.
100	func TestCorruptCircuitRecordFieldsRefused(t *testing.T) {
101		damage := []struct {
102			name      string
103			mutate    func(map[string]any)
104			wantField string
105		}{
106			{"missing name", deleteCircuitField("name"), `"name"`},
107			{"null name", setCircuitField("name", nil), `"name"`},
108			{"numeric name", setCircuitField("name", 7), `"name"`},
109			{"missing version", deleteCircuitField("version"), `"version"`},
110			{"null version", setCircuitField("version", nil), `"version"`},
111			{"string version", setCircuitField("version", "1"), `"version"`},
112			{"float version", setCircuitField("version", 1.5), `"version"`},
113			{"missing constraints", deleteCircuitField("constraints"), `"constraints"`},
114			{"null constraints", setCircuitField("constraints", nil), `"constraints"`},
115			{"string constraints", setCircuitField("constraints", "1"), `"constraints"`},
116			{"missing public_inputs", deleteCircuitField("public_inputs"), `"public_inputs"`},
117			{"null public_inputs", setCircuitField("public_inputs", nil), `"public_inputs"`},
118			{"float public_inputs", setCircuitField("public_inputs", 0.5), `"public_inputs"`},
119			{"string public_inputs", setCircuitField("public_inputs", "0"), `"public_inputs"`},
120			{"missing private_inputs", deleteCircuitField("private_inputs"), `"private_inputs"`},
121			{"null private_inputs", setCircuitField("private_inputs", nil), `"private_inputs"`},
122			{"bool private_inputs", setCircuitField("private_inputs", true), `"private_inputs"`},
123			// The headline damage: a frozen record whose frozen flag is deleted or
124			// null must not come back as an editable draft.
125			{"missing frozen", deleteCircuitField("frozen"), `"frozen"`},
126			{"null frozen", setCircuitField("frozen", nil), `"frozen"`},
127			{"string frozen", setCircuitField("frozen", "true"), `"frozen"`},
128			{"numeric frozen", setCircuitField("frozen", 1), `"frozen"`},
129			{"missing description", deleteCircuitField("description"), `"description"`},
130			{"null description", setCircuitField("description", nil), `"description"`},
131			{"numeric description", setCircuitField("description", 1), `"description"`},
132		}
133	
134		for _, frozen := range []bool{false, true} {
135			state := "draft"
136			if frozen {
137				state = "frozen-setup-compiled"
138			}
139			t.Run(state, func(t *testing.T) {
140				for _, tc := range damage {
141					t.Run(tc.name, func(t *testing.T) {
142						dir := seedClosedStore(t, frozen)
143						env := readGenericEnv(t, dir)
144						tc.mutate(env)
145						bad := writeGenericEnv(t, dir, env)
146						requireCorruptAndUntouched(t, dir, bad, tc.wantField)
