153	// compactCircuitRecord extracts the first circuit record from a raw envelope
154	// and returns it compacted, plus a function to re-embed a replacement.
155	func compactCircuitRecord(t *testing.T, raw []byte) (record []byte, embed func([]byte) []byte) {
156		t.Helper()
157		var wire struct {
158			Circuits []json.RawMessage `json:"circuits"`
159		}
160		if err := json.Unmarshal(raw, &wire); err != nil {
161			t.Fatal(err)
162		}
163		orig := []byte(wire.Circuits[0])
164		var compact bytes.Buffer
165		if err := json.Compact(&compact, orig); err != nil {
166			t.Fatal(err)
167		}
168		return compact.Bytes(), func(rep []byte) []byte {
169			return bytes.Replace(raw, orig, rep, 1)
170		}
171	}
172	
173	// appendRecordField returns a compact record JSON copy with an extra raw
174	// member inserted before the closing brace: `...,"field":value`.
175	func appendRecordField(t *testing.T, record []byte, member string) []byte {
176		t.Helper()
177		if len(record) == 0 || record[len(record)-1] != '}' {
178			t.Fatalf("record does not end with }: %s", record)
179		}
180		out := make([]byte, 0, len(record)+len(member)+1)
181		out = append(out, record[:len(record)-1]...)
182		out = append(out, ',')
183		out = append(out, member...)
184		out = append(out, '}')
185		// Must stay parseable JSON.
186		var probe map[string]json.RawMessage
187		if err := json.Unmarshal(out, &probe); err != nil {
188			t.Fatalf("crafted record is not valid JSON: %v (%s)", err, out)
189		}
190		return out
191	}
