193	// TestDuplicateCircuitFieldsRefused: every field appearing twice is
194	// corruption — with a differing value, with the same value, and when one
195	// occurrence spells the key through a JSON escape (encoding/json decodes the
196	// escaped key to the same string and would otherwise keep one value).
197	func TestDuplicateCircuitFieldsRefused(t *testing.T) {
198		fields := []string{
199			"name", "version", "constraints", "public_inputs",
200			"private_inputs", "frozen", "description",
201		}
202		values := map[string]string{
203			"name": `"other"`, "version": `2`, "constraints": `9`,
204			"public_inputs": `4`, "private_inputs": `5`,
205			"description": `"changed"`,
206		}
207		// escapedKey spells one byte of the key as \u00XX: JSON decoding makes it
208		// the identical member name, so it is still a duplicate.
209		escapedKey := func(key string) string {
210			return fmt.Sprintf("\"\\u%04x%s\"", key[0], key[1:])
211		}
212	
213		for _, frozen := range []bool{false, true} {
214			// The duplicated value differs from the stored one: flip frozen.
215			values["frozen"] = `true`
