231						rec, embed := compactCircuitRecord(t, raw)
232						badRec := appendRecordField(t, rec, fmt.Sprintf("%q:%s", field, values[field]))
233						bad := embed(badRec)
234						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
235							t.Fatal(err)
236						}
237						requireCorruptAndUntouched(t, dir, bad, field)
238					})
239					t.Run(field+"/same value", func(t *testing.T) {
240						dir := seedClosedStore(t, frozen)
241						raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
242						if err != nil {
243							t.Fatal(err)
244						}
245						rec, embed := compactCircuitRecord(t, raw)
246						var probe map[string]json.RawMessage
247						if err := json.Unmarshal(rec, &probe); err != nil {
248							t.Fatal(err)
249						}
250						badRec := appendRecordField(t, rec,
251							fmt.Sprintf("%q:%s", field, string(probe[field])))
252						bad := embed(badRec)
253						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
254							t.Fatal(err)
255						}
256						requireCorruptAndUntouched(t, dir, bad, field)
257					})
258					t.Run(field+"/escaped key", func(t *testing.T) {
259						dir := seedClosedStore(t, frozen)
260						raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
261						if err != nil {
262							t.Fatal(err)
263						}
264						rec, embed := compactCircuitRecord(t, raw)
265						var probe map[string]json.RawMessage
266						if err := json.Unmarshal(rec, &probe); err != nil {
267							t.Fatal(err)
268						}
269						// The second occurrence escapes one byte of the key; it is
270						// the same JSON field name.
271						badRec := appendRecordField(t, rec,
272							escapedKey(field)+":"+string(probe[field]))
273						bad := embed(badRec)
274						if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
275							t.Fatal(err)
276						}
277						requireCorruptAndUntouched(t, dir, bad, field)
278					})
279				}
280			})
281		}
282	}
