284	// TestUnknownCircuitFieldRefused: a committed record may only carry the
285	// fields the writer emits; an unknown member is refused instead of being
286	// silently ignored (a typo next to a real required field must not pass).
287	func TestUnknownCircuitFieldRefused(t *testing.T) {
288		for _, field := range []string{`"note":"x"`, `"frzoen":true`} {
289			t.Run(field, func(t *testing.T) {
290				dir := seedClosedStore(t, true)
291				raw, err := os.ReadFile(filepath.Join(dir, dirDataFile))
292				if err != nil {
293					t.Fatal(err)
294				}
295				rec, embed := compactCircuitRecord(t, raw)
296				badRec := appendRecordField(t, rec, field)
297				bad := embed(badRec)
298				if err := os.WriteFile(filepath.Join(dir, dirDataFile), bad, 0o644); err != nil {
299					t.Fatal(err)
300				}
301				requireCorruptAndUntouched(t, dir, bad, "unknown field")
302			})
303		}
304	}
305	
306	// TestDuplicateEnvelopeFieldRefused: a repeated top-level envelope key is
307	// also refused rather than resolved to its last value.
308	func TestDuplicateEnvelopeFieldRefused(t *testing.T) {
309		dir := seedClosedStore(t, false)
310		path := filepath.Join(dir, dirDataFile)
311		raw, err := os.ReadFile(path)
312		if err != nil {
313			t.Fatal(err)
314		}
315		var compact bytes.Buffer
316		if err := json.Compact(&compact, raw); err != nil {
317			t.Fatal(err)
318		}
319		body := bytes.TrimSuffix(compact.Bytes(), []byte("}"))
320		bad := append(append([]byte(nil), body...), []byte(`,"jobs":[]}`)...)
321		if err := os.WriteFile(path, bad, 0o644); err != nil {
322			t.Fatal(err)
323		}
324		requireCorruptAndUntouched(t, dir, bad, "jobs")
325	}
326	
327	// TestExplicitZeroFalseEmptyAreLegal pins the other half of the contract: an
328	// explicitly stored public/private count of 0, frozen:false and an empty
329	// description are ordinary values and must survive a reload unchanged — they
330	// must never be mistaken for a missing field.
331	func TestExplicitZeroFalseEmptyAreLegal(t *testing.T) {
332		dir := filepath.Join(t.TempDir(), "bench")
333		s, err := Open(dir)
334		if err != nil {
335			t.Fatal(err)
336		}
337		if _, err := s.CreateCircuit(Circuit{Name: "zero", Version: 1, Constraints: 3,
338			PublicInputs: 0, PrivateInputs: 0, Frozen: false, Description: ""}); err != nil {
339			t.Fatal(err)
340		}
341		if err := s.Close(); err != nil {
342			t.Fatal(err)
343		}
344	
345		// Hand-assert the on-disk record carries the explicit fields.
346		env := readGenericEnv(t, dir)
347		rec := readFirstCircuit(env)
348		for _, key := range []string{"name", "version", "constraints", "public_inputs",
349			"private_inputs", "frozen", "description"} {
350			if _, ok := rec[key]; !ok {
351				t.Fatalf("writer omitted %q", key)
352			}
353		}
354		if rec["public_inputs"] != float64(0) || rec["private_inputs"] != float64(0) ||
355			rec["frozen"] != false || rec["description"] != "" {
356			t.Fatalf("unexpected stored record: %+v", rec)
357		}
358	
359		s2, err := Open(dir)
360		if err != nil {
361			t.Fatalf("explicit 0/false/\"\" rejected on reload: %v", err)
362		}
363		defer s2.Close()
364		got, err := s2.GetCircuit("zero", 1)
365		if err != nil {
366			t.Fatal(err)
367		}
368		if got.PublicInputs != 0 || got.PrivateInputs != 0 || got.Frozen || got.Description != "" {
369			t.Fatalf("reloaded record drifted: %+v", got)
370		}
371		// The draft remains genuinely editable: an empty-description update with
372		// zero inputs succeeds, proving frozen:false was not conflated with
373		// "unset".
374		zero := 0
375		empty := ""
376		if _, err := s2.UpdateCircuitPartial("zero", 1, PartialCircuit{
377			PublicInputs: &zero, Description: &empty,
378		}); err != nil {
379			t.Fatalf("draft update refused: %v", err)
380		}
381	}
382	
383	// TestCorruptRecordFailsWholeDirectory: one damaged record poisons every
384	// read even while a healthy record sits next to it — no partial results, and
385	// mutating, freezing and compiling operations neither succeed nor commit.
386	func TestCorruptRecordFailsWholeDirectory(t *testing.T) {
387		dir := seedClosedStore(t, true)
388		s, err := Open(dir)
389		if err != nil {
390			t.Fatal(err)
391		}
392		// Add a second, healthy record while the store is open.
393		if _, err := s.CreateCircuit(Circuit{Name: "good", Version: 9, Constraints: 1,
394			Description: "fine"}); err != nil {
395			t.Fatal(err)
396		}
397		if err := s.Close(); err != nil {
398			t.Fatal(err)
399		}
400	
401		env := readGenericEnv(t, dir)
402		readFirstCircuit(env)["frozen"] = nil // damage the first (frozen) record
403		bad := writeGenericEnv(t, dir, env)
404	
405		before, err := os.ReadFile(filepath.Join(dir, dirDataFile))
406		if err != nil || string(before) != string(bad) {
407			t.Fatalf("setup mismatch")
408		}
409	
410		// Reads: whole-directory and single-record queries both fail.
411		s2, err := Open(dir)
412		if err == nil {
413			defer s2.Close()
414			if _, lerr := s2.ListCircuits(); !errors.Is(lerr, ErrDataCorrupt) {
415				t.Fatalf("ListCircuits: want ErrDataCorrupt, got %v", lerr)
416			}
417			if _, gerr := s2.GetCircuit("good", 9); !errors.Is(gerr, ErrDataCorrupt) {
418				t.Fatalf("GetCircuit on the healthy record: want ErrDataCorrupt, got %v", gerr)
419			}
420			if _, _, serr := s2.GetSetup("mul", 1); !errors.Is(serr, ErrDataCorrupt) {
421				t.Fatalf("GetSetup: want ErrDataCorrupt, got %v", serr)
422			}
423			// Mutations on the healthy draft never commit.
424			if _, uerr := s2.UpdateCircuit(Circuit{Name: "good", Version: 9, Constraints: 4,
425				Description: "x"}); !errors.Is(uerr, ErrDataCorrupt) {
426				t.Fatalf("UpdateCircuit: want ErrDataCorrupt, got %v", uerr)
427			}
428			if _, ferr := s2.FreezeCircuit("good", 9); !errors.Is(ferr, ErrDataCorrupt) {
429				t.Fatalf("FreezeCircuit: want ErrDataCorrupt, got %v", ferr)
430			}
431			if _, ierr := s2.ImportConstraints("good", 9, writeTempJSON(t,
432				`{"modulus":"7","constraints":[]}`)); !errors.Is(ierr, ErrDataCorrupt) {
433				t.Fatalf("ImportConstraints: want ErrDataCorrupt, got %v", ierr)
434			}
435			if _, aerr := s2.CreateCircuit(Circuit{Name: "new", Version: 1, Constraints: 1,
436				Description: "d"}); !errors.Is(aerr, ErrDataCorrupt) {
437				t.Fatalf("CreateCircuit: want ErrDataCorrupt, got %v", aerr)
438			}
439			if _, cerr := s2.CompileCircuit("mul", 1); !errors.Is(cerr, ErrDataCorrupt) {
440				t.Fatalf("CompileCircuit: want ErrDataCorrupt, got %v", cerr)
441			}
442		} else if !errors.Is(err, ErrDataCorrupt) {
443			t.Fatalf("Open: want ErrDataCorrupt, got %v", err)
444		}
445	
446		left, err := os.ReadFile(filepath.Join(dir, dirDataFile))
447		if err != nil {
448			t.Fatal(err)
449		}
450		if string(left) != string(bad) {
451			t.Fatalf("refused operation committed state")
452		}
453	}
454	
455	// TestCorruptionDiscoveredAfterOpen: the directory opens cleanly, the file is
456	// damaged by an external editor, and the next operation's re-read must fail
457	// closed without committing.
458	func TestCorruptionDiscoveredAfterOpen(t *testing.T) {
459		dir := seedClosedStore(t, false)
460		s, err := Open(dir)
461		if err != nil {
462			t.Fatal(err)
463		}
464		defer s.Close()
465		// First read is healthy.
466		if _, err := s.GetCircuit("mul", 1); err != nil {
467			t.Fatal(err)
468		}
469	
470		// External damage while the handle stays open: drop the frozen flag.
471		env := readGenericEnv(t, dir)
472		delete(readFirstCircuit(env), "frozen")
473		bad := writeGenericEnv(t, dir, env)
474	
475		// A read path that reloads under the shared lock must fail.
476		if _, err := s.ListCircuits(); !errors.Is(err, ErrDataCorrupt) {
477			t.Fatalf("ListCircuits after tamper: want ErrDataCorrupt, got %v", err)
478		}
479		// A mutating path must not succeed, and crucially must not "repair" the
480		// file by committing in-memory state over the damage.
481		if _, err := s.FreezeCircuit("mul", 1); !errors.Is(err, ErrDataCorrupt) {
482			t.Fatalf("FreezeCircuit after tamper: want ErrDataCorrupt, got %v", err)
483		}
484		left, err := os.ReadFile(filepath.Join(dir, dirDataFile))
485		if err != nil {
486			t.Fatal(err)
487		}
488		if string(left) != string(bad) {
489			t.Fatalf("tampered data.json was overwritten")
490		}
491	}
492	
493	// TestFrozenRecordTamperingCannotReopenAsDraft is the exact bug from the
494	// repair rule: frozen deleted/null must not make a frozen version editable.
495	func TestFrozenRecordTamperingCannotReopenAsDraft(t *testing.T) {
496		for _, mode := range []string{"deleted", "null"} {
497			t.Run(mode, func(t *testing.T) {
498				dir := seedClosedStore(t, true)
499				env := readGenericEnv(t, dir)
500				if mode == "deleted" {
501					delete(readFirstCircuit(env), "frozen")
502				} else {
503					readFirstCircuit(env)["frozen"] = nil
504				}
505				bad := writeGenericEnv(t, dir, env)
506	
507				s, err := Open(dir)
508				if err == nil {
509					defer s.Close()
510					t.Fatalf("damaged frozen record opened")
511				}
512				if !errors.Is(err, ErrDataCorrupt) || !strings.Contains(err.Error(), `"frozen"`) {
513					t.Fatalf("want ErrDataCorrupt naming frozen, got %v", err)
514				}
515				left, _ := os.ReadFile(filepath.Join(dir, dirDataFile))
516				if string(left) != string(bad) {
517					t.Fatalf("data.json changed")
518				}
519			})
520		}
521	}
