// matching the writer) and returns the exact bytes written.
func writeRawEnvelope(t *testing.T, dir string, records ...string) []byte {
	t.Helper()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	content := `{"format":1,"circuits":[` + strings.Join(records, ",") +
		`],"setups":[],"jobs":[]}` + "\n"
